#!/usr/bin/env python3
"""Apply byte-verified DarkWolf IFSM V2 selection, persistence and smoothing patch.
Exact source lineage: 43189244002 + accepted V1.2 43435737255.
"""
from pathlib import Path
import base64,bz2,hashlib,json,subprocess,sys,tempfile
source=Path(sys.argv[1] if len(sys.argv)>1 else 'source').resolve()
evidence=Path(sys.argv[2] if len(sys.argv)>2 else 'evidence').resolve()
evidence.mkdir(parents=True,exist_ok=True)
root=source/'SP/code/rend2'
pre={'tr_scene.c': 'f4505ba9a014bb8d6edbfe383bdc8272616f4da883f2a811499f060c0984e44e', 'tr_local.h': '85a184b755fe671829559505e00a311a6ed2bbb4e341464533deaa287832b878', 'tr_init.c': 'd2f4cf9c7e3c70319c4dd8f8a0a9cf5853cf60d29719b406c92b4d1fc50522a6', 'tr_bsp.c': 'cc06e67d00403947bf30a423c5b22d95a735636dbe9e833a53d2c9b91fcc3faa'}
post={'tr_scene.c': '76a06d950c43aeadd47785dea3b51d5db26fcf3abdb6c97d1de05cd89bf57102', 'tr_local.h': 'da1230aec037de81f5ce65e3c00b2d28b061c0d98028023c11530e508a33c3f8', 'tr_init.c': '94224cf6840b4c964c5b24846e805572f52c1ece8a3346bcb20bd61510200e09', 'tr_bsp.c': 'ffb81371cf40da035ec8426ce3b4d539e5c94fd78deb1653d78bb394030bd4d6', 'tr_fsm_editor.inc': '783bf3b5b7ce7ce62a5f663ad3ac0d5273737ca652f2a86c325b91897704029b'}
expected_patch_sha256='3dd91049d670fe5ab3ed2eb6ab5e9f6108dc16779a50957335e9eb8e62c9421c'
payload=''
patch=bz2.decompress(base64.b64decode(payload))
assert hashlib.sha256(patch).hexdigest()==expected_patch_sha256, 'Patch integrity failure'
sha=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
for rel,digest in pre.items():
    file=root/rel
    assert file.is_file() and sha(file)==digest,('WRONG_FSM_V12_BASE',rel,sha(file) if file.exists() else None)
assert not (root/'tr_fsm_editor.inc').exists(),'Editor already installed'
with tempfile.TemporaryDirectory() as td:
    file=Path(td)/'ifsm_v2.patch'
    file.write_bytes(patch)
    subprocess.run(['git','-C',str(source),'apply','--check',str(file)],check=True)
    subprocess.run(['git','-C',str(source),'apply',str(file)],check=True)
for rel,digest in post.items():
    file=root/rel
    assert file.is_file() and sha(file)==digest,('BAD_IFSM_V2_POST',rel,sha(file) if file.exists() else None)
assert 'FIRE_SHADOW_MOTION_V12' in (root/'glsl/dlight_fp.glsl').read_text()
assert 'FIRE_SHADOW_MOTION_V12' in (root/'glsl/lightall_fp.glsl').read_text()
assert 'vec2 softSample = samplePos + (unbounded - samplePos) * spread;' not in (root/'glsl/dlight_fp.glsl').read_text()
proof={'source_base_run':43189244002,'accepted_motion_run':43435737255,
       'patch_sha256':expected_patch_sha256,'changed_files':sorted(post),
       'source_sha256_before':pre,'source_sha256_after':post,
       'glsl_modified':False,'max_selected_sources':2,
       'default_global_motion':'OFF','profiles_autosaved':True,
       'surface_bridge':'existing R_IFLC_AddOptIn guarded implementation',
       'step_ms_1_source':33,'step_ms_2_sources_min':50,
       'gpu_visual_pass':False}
(evidence/'DW_IFSM_V2_SOURCE_PROOF.json').write_text(json.dumps(proof,indent=2)+'\n')
print('DW_IFSM_V2_EXACT_SOURCE_SCOPE_PASS', sorted(post))
